import { useState } from 'react'
import { FONT, palette, gradients } from '../theme'

const demoUsers = [
  { id: 1, name: 'Ana Ocampo', email: 'admin@aula.com', password: 'admin123', role: 'admin' },
  { id: 2, name: 'Carlos Mora', email: 'user@aula.com', password: 'user123', role: 'user' },
]

const inputBase = {
  width: '100%',
  padding: '14px 16px',
  fontSize: '15px',
  border: '1.5px solid rgba(255,255,255,0.22)',
  borderRadius: '14px',
  outline: 'none',
  boxSizing: 'border-box',
  background: 'rgba(255,255,255,0.08)',
  color: '#FFFFFF',
  transition: 'border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease',
  fontFamily: FONT,
}

const labelStyle = {
  display: 'block',
  fontSize: '13.5px',
  fontWeight: 600,
  color: 'rgba(255,255,255,0.85)',
  marginBottom: '8px',
  letterSpacing: '-0.01em',
}

export default function LoginForm({ onLogin }) {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [buttonHover, setButtonHover] = useState(false)
  const [adminHover, setAdminHover] = useState(false)
  const [userHover, setUserHover] = useState(false)
  const [emailFocused, setEmailFocused] = useState(false)
  const [pwdFocused, setPwdFocused] = useState(false)

  const loginUser = (found) =>
    onLogin({ id: found.id, name: found.name, email: found.email, role: found.role })

  const findUser = (users, emailValue, passwordValue) =>
    users.find(
      (u) =>
        u.email.toLowerCase() === emailValue.trim().toLowerCase() &&
        u.password === passwordValue
    )

  const handleSubmit = async (event) => {
    event.preventDefault()
    setError('')
    if (!email.trim() || !password.trim()) {
      setError('Por favor completa el correo y la contraseña.')
      return
    }
    setLoading(true)
    try {
      const response = await fetch('/api/users')
      const users = await response.json()
      const found = findUser(users, email, password)
      if (!found) {
        setError('Credenciales incorrectas. Revisa tu correo y contraseña.')
        return
      }
      loginUser(found)
    } catch {
      const found = findUser(demoUsers, email, password)
      if (!found) {
        setError('No se pudo conectar con JSON Server. Usa los botones demo o ejecuta "npm run server".')
        return
      }
      loginUser(found)
    } finally {
      setLoading(false)
    }
  }

  const handleDemo = (role) => {
    const found = demoUsers.find((u) => u.role === role)
    loginUser(found)
  }

  return (
    <div
      style={{
        minHeight: '100vh',
        background: gradients.app,
        fontFamily: FONT,
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      {/* Elementos decorativos */}
      <div style={{ position: 'absolute', top: '-140px', left: '-120px', width: '520px', height: '520px', borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,255,255,0.14) 0%, transparent 70%)', pointerEvents: 'none' }} />
      <div style={{ position: 'absolute', bottom: '-180px', right: '-160px', width: '580px', height: '580px', borderRadius: '50%', background: 'radial-gradient(circle, rgba(245, 179, 1, 0.16) 0%, transparent 70%)', pointerEvents: 'none' }} />
      <div style={{ position: 'absolute', top: '26%', right: '34%', width: '340px', height: '340px', borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,255,255,0.10) 0%, transparent 70%)', pointerEvents: 'none' }} />

      <div
        className="login-shell"
        style={{
          position: 'relative',
          zIndex: 1,
          minHeight: '100vh',
          maxWidth: '1280px',
          margin: '0 auto',
          padding: '48px 40px',
          display: 'grid',
          alignItems: 'center',
          boxSizing: 'border-box',
        }}
      >
        {/* Panel de marca: logo grande + textos */}
        <div className="login-brand" style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', animation: 'fadeInUp 0.6s ease both' }}>
            <img
              src="data:image/png;base64,"
              alt="Logotipo AulaDigital Pro"
              style={{
                width: 'clamp(120px, 14vw, 170px)',
                height: 'clamp(120px, 14vw, 170px)',
                objectFit: 'contain',
                filter: 'drop-shadow(0 20px 40px rgba(20, 5, 45, 0.5))',
              }}
            />
            <h1
              style={{
                margin: '26px 0 8px',
                fontFamily: FONT,
                fontSize: 'clamp(38px, 5vw, 58px)',
                fontWeight: 900,
                lineHeight: 1.02,
                letterSpacing: '-0.045em',
                color: '#FFFFFF',
              }}
            >
              AulaDigital<span style={{ color: palette.goldBright }}>Pro</span>
            </h1>
            <p style={{ fontSize: 'clamp(16px, 1.6vw, 19px)', fontWeight: 600, color: 'rgba(255,255,255,0.92)', letterSpacing: '-0.01em', margin: '0 0 22px' }}>
              Soluciones de aprendizaje pro
            </p>
            <span className="login-rule" style={{ width: 64, height: 4, borderRadius: 999, background: gradients.gold, marginBottom: 22 }} />
            <p style={{ fontSize: 15, lineHeight: 1.7, color: 'rgba(255,255,255,0.78)', maxWidth: 420, margin: 0 }}>
              Accede a cursos prácticos, proyectos reales y acompañamiento experto para avanzar con confianza en el mundo digital.
            </p>
          </div>
        </div>

        {/* Formulario de acceso */}
        <form
          onSubmit={handleSubmit}
          className="login-form-card"
          style={{
            width: '100%',
            maxWidth: 460,
            marginLeft: 'auto',
            border: '1px solid rgba(255,255,255,0.22)',
            borderRadius: 26,
            padding: '40px 38px',
            boxSizing: 'border-box',
            background: 'rgba(12, 14, 38, 0.55)',
            boxShadow: '0 32px 80px rgba(20, 5, 45, 0.5)',
            backdropFilter: 'blur(16px)',
            WebkitBackdropFilter: 'blur(12px)',
            animation: 'fadeInUp 0.6s 0.08s ease both',
          }}
        >
          <h2 style={{ fontSize: 28, fontWeight: 800, color: '#FFFFFF', margin: '0 0 8px', letterSpacing: '-0.02em', fontFamily: FONT }}>
            Iniciar sesión
          </h2>
          <p style={{ fontSize: 15, color: 'rgba(255,255,255,0.7)', margin: '0 0 30px', lineHeight: 1.55 }}>
            Accede a tus cursos y continúa tu aprendizaje.
          </p>

          <div style={{ marginBottom: 20 }}>
            <label htmlFor="email" style={labelStyle}>Correo electrónico</label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              onFocus={() => setEmailFocused(true)}
              onBlur={() => setEmailFocused(false)}
              placeholder="tu@email.com"
              style={{ ...inputBase, borderColor: emailFocused ? palette.goldBright : 'rgba(255,255,255,0.22)', boxShadow: emailFocused ? '0 0 0 4px rgba(245, 179, 1, 0.18)' : 'none', background: emailFocused ? 'rgba(255,255,255,0.14)' : 'rgba(255,255,255,0.08)' }}
            />
          </div>

          <div style={{ marginBottom: 28 }}>
            <label htmlFor="password" style={labelStyle}>Contraseña</label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              onFocus={() => setPwdFocused(true)}
              onBlur={() => setPwdFocused(false)}
              placeholder="••••••••"
              style={{ ...inputBase, borderColor: pwdFocused ? palette.goldBright : 'rgba(255,255,255,0.22)', boxShadow: pwdFocused ? '0 0 0 4px rgba(245, 179, 1, 0.18)' : 'none', background: pwdFocused ? 'rgba(255,255,255,0.14)' : 'rgba(255,255,255,0.08)' }}
            />
          </div>

          {error && (
            <div style={{ background: 'rgba(220, 38, 38, 0.16)', border: '1px solid rgba(252, 165, 165, 0.4)', color: '#FECACA', fontSize: 13.5, fontWeight: 500, padding: '12px 16px', borderRadius: 12, marginBottom: 20, lineHeight: 1.5 }}>
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            onMouseEnter={() => setButtonHover(true)}
            onMouseLeave={() => setButtonHover(false)}
            style={{
              width: '100%',
              padding: 15,
              background: loading ? '#A5B4FC' : gradients.btn,
              color: '#fff',
              fontSize: 16,
              fontWeight: 800,
              border: 'none',
              borderRadius: 14,
              cursor: loading ? 'not-allowed' : 'pointer',
              boxShadow: buttonHover && !loading ? '0 16px 30px rgba(109,40,217,0.4)' : '0 10px 20px rgba(109,40,217,0.28)',
              transform: buttonHover && !loading ? 'translateY(-2px)' : 'none',
              transition: 'all 0.25s ease',
              letterSpacing: '-0.01em',
              fontFamily: FONT,
            }}
          >
            {loading ? 'Verificando...' : 'Iniciar sesión'}
          </button>

          <div style={{ display: 'flex', alignItems: 'center', gap: 12, margin: '24px 0', fontSize: 13, color: 'rgba(255,255,255,0.6)' }}>
            <span style={{ flex: 1, height: 1, background: 'rgba(255,255,255,0.18)' }} />
            o prueba una cuenta demo
            <span style={{ flex: 1, height: 1, background: 'rgba(255,255,255,0.18)' }} />
          </div>

          <div style={{ display: 'flex', gap: 12 }}>
            <button
              type="button"
              onClick={() => handleDemo('admin')}
              onMouseEnter={() => setAdminHover(true)}
              onMouseLeave={() => setAdminHover(false)}
              style={{ flex: 1, padding: 12, background: adminHover ? 'rgba(245,179,1,0.18)' : 'rgba(245,179,1,0.08)', color: palette.goldBright, fontSize: 13.5, fontWeight: 700, border: `1.5px solid ${adminHover ? 'rgba(245,179,1,0.7)' : 'rgba(245,179,1,0.35)'}`, borderRadius: 12, cursor: 'pointer', fontFamily: FONT, transition: 'all 0.2s ease', transform: adminHover ? 'translateY(-2px)' : 'none', boxShadow: adminHover ? '0 8px 16px rgba(245,179,1,0.18)' : 'none' }}
            >
              Entrar como Admin
            </button>
            <button
              type="button"
              onClick={() => handleDemo('user')}
              onMouseEnter={() => setUserHover(true)}
              onMouseLeave={() => setUserHover(false)}
              style={{ flex: 1, padding: 12, background: '#FFFFFF', color: palette.ink, fontSize: 13.5, fontWeight: 700, border: `1.5px solid ${palette.line}`, borderRadius: 12, cursor: 'pointer', fontFamily: FONT, transition: 'all 0.2s ease', transform: userHover ? 'translateY(-2px)' : 'none', boxShadow: userHover ? '0 8px 16px rgba(15,23,42,0.08)' : 'none' }}
            >
              Entrar como Usuario
            </button>
          </div>

          <p style={{ fontSize: 12, color: 'rgba(255,255,255,0.55)', margin: '20px 0 0', textAlign: 'center', lineHeight: 1.6 }}>
            Admin: admin@aula.com / admin123 · Usuario: user@aula.com / user123
          </p>
        </form>
      </div>
    </div>
  )
}